// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Hybrid introsort with median-of-three pivot, insertion sort for small subarrays, and nearly-sorted detection will improve performance and adaptability
// MECHANISM-1: Median-of-three avoids worst-case pivots, insertion sort is optimal for small n, and detecting sorted runs avoids unnecessary work
// EXPECT-1: combined_score > 0.99
// RESULT-1: CONFIRMED (actual=0.9982782446720482)

pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 {
        return;
    }
    // Check if nearly sorted (O(n) check) - use insertion sort which is O(n) for nearly sorted
    if nearly_sorted(arr) {
        insertion_sort(arr);
        return;
    }
    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, 0, len - 1, max_depth);
}

fn nearly_sorted<T: Ord>(arr: &[T]) -> bool {
    let mut disorder = 0usize;
    let limit = arr.len() / 8 + 1;
    for i in 1..arr.len() {
        if arr[i - 1] > arr[i] {
            disorder += 1;
            if disorder > limit {
                return false;
            }
        }
    }
    true
}

fn introsort<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize, depth: usize) {
    let len = high - low + 1;
    if len <= 16 {
        insertion_sort_range(arr, low, high);
        return;
    }
    if depth == 0 {
        heapsort_range(arr, low, high);
        return;
    }
    let p = partition_mo3(arr, low, high);
    if p > low {
        introsort(arr, low, p - 1, depth - 1);
    }
    if p < high {
        introsort(arr, p + 1, high, depth - 1);
    }
}

fn partition_mo3<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize) -> usize {
    let mid = low + (high - low) / 2;
    // Median-of-three pivot selection
    if arr[mid] < arr[low] { arr.swap(low, mid); }
    if arr[high] < arr[low] { arr.swap(low, high); }
    if arr[high] < arr[mid] { arr.swap(mid, high); }
    arr.swap(mid, high);
    let pivot = arr[high].clone();
    let mut i = low;
    for j in low..high {
        if arr[j] <= pivot {
            arr.swap(i, j);
            i += 1;
        }
    }
    arr.swap(i, high);
    i
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}

fn insertion_sort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    for i in (low + 1)..=high {
        let mut j = i;
        while j > low && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}

fn heapsort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    let len = high - low + 1;
    for i in (0..len / 2).rev() {
        sift_down(arr, low, i, len);
    }
    for i in (1..len).rev() {
        arr.swap(low, low + i);
        sift_down(arr, low, 0, i);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], base: usize, start: usize, len: usize) {
    let mut root = start;
    loop {
        let child = 2 * root + 1;
        if child >= len { break; }
        let swap = if child + 1 < len && arr[base + child] < arr[base + child + 1] {
            child + 1
        } else {
            child
        };
        if arr[base + root] < arr[base + swap] {
            arr.swap(base + root, base + swap);
            root = swap;
        } else {
            break;
        }
    }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

